@startuml

class User {
  + UserID : int
  + Name : string
  + Address : string
  + Birthday : date
}

class BusinessOwner {
  + LinkedInAccount : string
}

class HungryCustomer {
  + DeliveryAddress : string
}

class Entertainer {
  + StageName : string
  + Bio : string
  + PricePer30Min : float
}

class Restaurant {
  + ZipCode : string
  + Address : string
  + PhoneNumber : string
  + Website : string
  + OpeningHours : string
}

class Pizza {
  + Name : string
  + CrustStructure : string
  + Price : float
}

class Order {
  + OrderID : int
  + OrderDateTime : datetime
  + LatestDeliveryTime : time
  + NumberOfPeople : int
}

class EntertainmentOrder {
  + EntertainmentType : string
  + Duration : int
}

enum Day {
  Monday
  Tuesday
  Wednesday
  Thursday
  Friday
  Saturday
  Sunday
}

User --|> BusinessOwner
User --|> HungryCustomer
User --|> Entertainer

BusinessOwner "1" -- "1..*" Restaurant : owns
Restaurant "1" -- "*" Pizza : offers
HungryCustomer "1" -- "*" Order : places
Order "1" -- "1..*" Pizza : contains
Order <|-- EntertainmentOrder
EntertainmentOrder "*" -- "1" Entertainer : fulfilledBy
Entertainer "1" -- "*" Restaurant : worksAt
Entertainer "*" -- "0..*" Day : availability

@enduml

